def minDistinctFreqPair(nums):
    # Count the frequency of every value
    freq = {}
    for x in nums:
        freq[x] = freq.get(x, 0) + 1

    # Distinct values in increasing order
    vals = sorted(freq)

    # The first (x, y) found in sorted order is the smallest x, then smallest y
    for i in range(len(vals)):
        for j in range(i + 1, len(vals)):
            if freq[vals[i]] != freq[vals[j]]:
                return [vals[i], vals[j]]

    # No pair with different frequencies exists
    return [-1, -1]
